      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Bug fix implementation",
      "activity_description": "Implement the code fix for the job creation error (e.g., proper request validation, container endpoint resolution, role-aware resource lookup) in the admin_ui backend and/or job service.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A4",
      "activity_name": "U1 - Error logging improvement",
      "activity_description": "Add structured ERROR-level logging with stack traces at the failure points; ensure container/admin logs surface the cause. Add unit/integration test covering the regression.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - Kafka explicit partition count: design and implementation",
      "activity_description": "Design the new `partitionCount` option on the Kafka module definition, add parsing/validation in the module options, and propagate to the Kafka producer configuration so the producer routes to the intended partition.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A6",
      "activity_name": "U2 - Kafka partition count testing",
      "activity_description": "Add unit and integration tests verifying the partitionCount option is honored and that payloads land on the configured consumer module/partition.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A7",
      "activity_name": "U3 - Dynamic partition subscription: design",
      "activity_description": "Design the dynamic partition discovery mechanism using Kafka AdminClient, including the polling interval, partition metadata refresh, and consumer rebalance integration with the KafkaMessageSourceContainer.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A8",
      "activity_name": "U3 - Dynamic partition subscription: implementation",
      "activity_description": "Implement the AdminClient-based partition discovery, wire it into the source container lifecycle, and trigger consumer rebalance on partition additions.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A9",
      "activity_name": "U3 - Dynamic partition subscription: testing",
      "activity_description": "Add tests covering initial subscription, dynamic partition addition at runtime, and verification that newly added partitions are consumed without restart.",
      "most_likely_effort": 1.0
    },
