      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A16",
      "activity_name": "U6 - Maven/Gradle module upload: testing",
      "activity_description": "Add tests that exercise the plugin tasks against a test admin server, including success, auth failure, and invalid module cases.",
      "most_likely_effort": 2.0
    },
    {
